import numpy as np

class RandomBaselineAgent:
    """Picks a random valid move on the board."""

    def choose_action(self, board: np.ndarray) -> int:
        """Select a random empty cell index (0-8)."""
        empty_cells = []
        for r in range(3):
            for c in range(3):
                if board[r, c] == 0:
                    empty_cells.append(r * 3 + c)
        return np.random.choice(empty_cells) if empty_cells else 0

